import type {
  Campaign, CampaignTemplate, Dashboard, DocumentResult, Encounter, EventProposal, Faction,
  GenerationEntry, Knowledge, Location, NPC, NPCCreate, ReferenceItem, Reward,
} from './types'

type View = 'session'|'tools'|'operations'|'simulation'|'world'|'party'|'players'|'knowledge'|'hexcrawl'|'combat'|'factions'|'library'|'reference'|'tables'
type GeneratorKind = 'encounter'|'reward'
type ConfigurableModule = View|'encounter'|'reward'
type UIPreferences = {
  modules:Record<ConfigurableModule,boolean>
  compact:boolean
  showContextPanel:boolean
  reduceMotion:boolean
  largeText:boolean
}

const UI_STORAGE_KEY='gm-ai-ui-preferences-v1'
const defaultPreferences:UIPreferences={
  modules:{session:true,tools:true,operations:true,simulation:true,world:true,party:true,players:true,knowledge:true,hexcrawl:true,combat:true,factions:true,library:true,reference:true,tables:true,encounter:true,reward:true},
  compact:false,showContextPanel:true,reduceMotion:false,largeText:false,
}
const navItems:[View,typeof LayoutDashboard,string,string][]=[
  ['session',LayoutDashboard,'Sessió','Dashboard, NPC i cronologia'],['tools',Dices,'Eines de taula','Daus, historial i condicions SRD'],['world',Map,'Món','Campanya, grup i localitzacions'],
  ['operations',FileText,'Operacions','Missions, calendari, clocks i planificació'],
  ['simulation',Bot,'Simulació','Agendes i accions dels NPC actius'],
  ['party',Users,'Grup i inventari','Personatges, equip i tresoreria'],
  ['players',Users,'Pantalla jugadors','Vista compartida i permisos'],['knowledge',BookOpen,'Coneixement','Capes DM, jugadors i món'],
  ['hexcrawl',Map,'Hexcrawl','Mapa, viatge i supervivència'],['combat',Swords,'Combat','Iniciativa, PG i accions'],
  ['factions',Shield,'Faccions','Organitzacions i reputació'],['library',Archive,'Biblioteca','Documents i mapes locals'],
  ['reference',BookOpen,'Catàleg SRD','Monstres, objectes i encanteris'],['tables',Dices,'Taules custom','Contingut homebrew contextual'],
]

function loadPreferences():UIPreferences{
  try{const saved=JSON.parse(localStorage.getItem(UI_STORAGE_KEY)??'{}') as Partial<UIPreferences>;return {...defaultPreferences,...saved,modules:{...defaultPreferences.modules,...saved.modules,session:true}}}catch{return defaultPreferences}
}

function loadInitialView():View{
  const requested=new URLSearchParams(window.location.search).get('view')
  return navItems.some(([id])=>id===requested)?requested as View:'session'
}

const terrainNames: Record<string,string> = {
  urban:'Ciutat', forest:'Bosc', jungle:'Selva', dungeon:'Dungeon', ruins:'Ruïnes',
  coast:'Costa', river:'Riu', swamp:'Pantà', mountain:'Muntanya', desert:'Desert', other:'Altres',
}
const terrains = Object.keys(terrainNames)
const difficultyNames = ['', 'Fàcil', 'Moderada', 'Mitjana', 'Difícil', 'Mortal']

function Field({label,children}:{label:string;children:React.ReactNode}) {
  return <label className="field"><span>{label}</span>{children}</label>
}

function Proposal({event,onDone}:{event:EventProposal;onDone:()=>void}) {
  const [draft,setDraft]=useState(event)
  const [busy,setBusy]=useState(false)
  const act=async(kind:'apply'|'ignore')=>{setBusy(true);try{if(kind==='apply')await api.applyEvent(event.id);else await api.ignoreEvent(event.id);onDone()}finally{setBusy(false)}}
  const save=async()=>{setBusy(true);try{setDraft(await api.updateEvent(event.id,{title:draft.title,severity:draft.severity,consequences:draft.consequences}))}finally{setBusy(false)}}
  return <section className="proposal">
    <div className="proposal-head"><span>Proposta pendent · {event.visibility==='public'?'públic':event.visibility==='witnessed'?'amb testimonis':'privat'}</span><em>Severitat {draft.severity}/10</em></div>
    <input className="title-input" value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/>
    <p>{draft.description}</p>
    <input type="range" min="1" max="10" value={draft.severity} onChange={e=>setDraft({...draft,severity:Number(e.target.value)})}/>
    <div className="consequences">{draft.consequences.map((item,index)=><div key={`${item.kind}-${index}`}><strong>{item.kind}</strong><span>{item.text||`${item.field}: ${item.delta>0?'+':''}${item.delta}`}</span></div>)}</div>
    <div className="button-row"><button onClick={()=>act('ignore')} disabled={busy}>Ignorar</button><button onClick={save} disabled={busy}><Save size={15}/> Desar edició</button><button className="primary" onClick={()=>act('apply')} disabled={busy}>Aplicar canvis</button></div>
  </section>
}

function NPCPanel({npc,data,close,changed}:{npc:NPC;data:Dashboard;close:()=>void;changed:()=>void}) {
  const [message,setMessage]=useState('');const [reply,setReply]=useState('');const [reasons,setReasons]=useState<string[]>([])
  const [memory,setMemory]=useState('');const [knowledge,setKnowledge]=useState<Knowledge[]>([]);const [newKnowledge,setNewKnowledge]=useState('');const [busy,setBusy]=useState(false)
  const [editing,setEditing]=useState(false);const [name,setName]=useState(npc.name);const [traits,setTraits]=useState(npc.traits.join(', '));const [goals,setGoals]=useState(npc.goals.join(', '));const [locationId,setLocationId]=useState(npc.location_id);const [factionId,setFactionId]=useState(npc.faction_id??'');const [active,setActive]=useState(npc.active);const [autonomy,setAutonomy]=useState(npc.autonomy)
  useEffect(()=>{void api.knowledge(npc.id).then(setKnowledge)},[npc.id])
  const send=async()=>{if(!message.trim())return;setBusy(true);try{const result=await api.chat(npc.id,message);setReply(result.reply);setReasons(result.context_reasons);setMessage('')}finally{setBusy(false)}}
  const addMemory=async()=>{if(!memory.trim())return;await api.addMemory(npc.id,memory);setMemory('');changed()}
  const addKnowledge=async()=>{if(!newKnowledge.trim())return;const item=await api.addKnowledge(npc.id,newKnowledge);setKnowledge([item,...knowledge]);setNewKnowledge('')}
  const saveNpc=async()=>{setBusy(true);try{await api.updateNpc(npc.id,{name,traits:traits.split(',').map(x=>x.trim()).filter(Boolean),goals:goals.split(',').map(x=>x.trim()).filter(Boolean),location_id:locationId,faction_id:factionId||undefined,active,autonomy});setEditing(false);changed()}finally{setBusy(false)}}
  const remove=async()=>{if(!confirm(`Eliminar ${npc.name}?`))return;await api.deleteNpc(npc.id);close();changed()}
  return <div className="drawer-overlay" onMouseDown={close}><aside className="npc-drawer" onMouseDown={e=>e.stopPropagation()}><button className="icon-button close" onClick={close}><X/></button>
    <span className="eyebrow">NPC persistent</span>{editing?<div className="edit-fields"><Field label="Nom"><input value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Localització"><select value={locationId} onChange={e=>setLocationId(e.target.value)}>{data.locations.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field><Field label="Facció"><select value={factionId} onChange={e=>setFactionId(e.target.value)}><option value="">Sense facció</option>{data.factions.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field><Field label="Trets"><input value={traits} onChange={e=>setTraits(e.target.value)}/></Field><Field label="Objectius"><input value={goals} onChange={e=>setGoals(e.target.value)}/></Field><div className="two-columns"><label className="toggle-inline"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/> NPC actiu</label><Field label="Autonomia"><select value={autonomy} disabled={!active} onChange={e=>setAutonomy(Number(e.target.value))}><option value="0">Pausa</option><option value="1">Baixa</option><option value="2">Mitjana</option><option value="3">Alta</option></select></Field></div><div className="button-row"><button className="danger" onClick={remove}><Trash2 size={14}/> Eliminar</button><button className="primary" onClick={saveNpc} disabled={busy}><Save size={14}/> Desar</button></div></div>:<><h2>{npc.name}</h2><p className="traits">{npc.traits.join(' · ')||'Sense trets definits'}</p><span className={`npc-mode ${npc.active?'active':''}`}>{npc.active?`Actiu · autonomia ${npc.autonomy}`:'Passiu'}</span><button onClick={()=>setEditing(true)}>Editar fitxa</button></>}
    <h4>Relació amb el grup</h4>{Object.entries(npc.relationship).map(([label,value])=><div className="relation" key={label}><span>{label}</span><div className="bar"><i className={value<0?'negative':''} style={{width:`${Math.abs(value)}%`}}/></div><b>{value}</b></div>)}
    <h4>Memòries</h4><div className="memory-list">{npc.memories.map(m=><p key={m.id}>{m.text}</p>)}{!npc.memories.length&&<p>Encara no té memòries rellevants.</p>}</div><div className="chat-input"><input value={memory} onChange={e=>setMemory(e.target.value)} placeholder="Afegir una memòria..."/><button onClick={addMemory}>Afegir</button></div>
    <details className="knowledge"><summary>Coneixement i creences ({knowledge.length})</summary>{knowledge.map(item=><div key={item.id}><span>{item.truth_status} · {Math.round(item.confidence*100)}%</span><p>{item.content}</p></div>)}<div className="chat-input"><input value={newKnowledge} onChange={e=>setNewKnowledge(e.target.value)} placeholder="Afegir coneixement..."/><button onClick={addKnowledge}>Afegir</button></div></details>
    <div className="chat"><h4><Bot size={15}/> Conversa contextual</h4>{reply&&<><div className="reply">{reply}</div><details><summary>Context utilitzat</summary>{reasons.map(reason=><p key={reason}>{reason}</p>)}</details></>}<div className="chat-input"><input value={message} onChange={e=>setMessage(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="Què diu el personatge?"/><button className="primary" onClick={send} disabled={busy}>Enviar</button></div></div>
  </aside></div>
}

function CreateNPC({data,close,done}:{data:Dashboard;close:()=>void;done:()=>void}) {
  const [name,setName]=useState('');const [traits,setTraits]=useState('');const [goals,setGoals]=useState('');const [location,setLocation]=useState(data.location.id);const [faction,setFaction]=useState('');const [active,setActive]=useState(false);const [busy,setBusy]=useState(false)
  const submit=async()=>{setBusy(true);try{const payload:NPCCreate={name,location_id:location,faction_id:faction||undefined,traits:traits.split(',').map(x=>x.trim()).filter(Boolean),goals:goals.split(',').map(x=>x.trim()).filter(Boolean),values:[],active,autonomy:1,relationship:{trust:0,respect:0,fear:0,affection:0}};await api.createNpc(data.campaign.id,payload);done()}finally{setBusy(false)}}
  return <div className="drawer-overlay" onMouseDown={close}><div className="modal" onMouseDown={e=>e.stopPropagation()}><button className="icon-button close" onClick={close}><X/></button><span className="eyebrow">Nou personatge</span><h2>Crear NPC</h2><Field label="Nom"><input value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Localització"><select value={location} onChange={e=>setLocation(e.target.value)}>{data.locations.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Facció"><select value={faction} onChange={e=>setFaction(e.target.value)}><option value="">Sense facció</option>{data.factions.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Trets, separats per comes"><input value={traits} onChange={e=>setTraits(e.target.value)}/></Field><Field label="Objectius"><input value={goals} onChange={e=>setGoals(e.target.value)}/></Field><label className="toggle-inline"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/> NPC actiu entre sessions</label><button className="primary full" disabled={busy||name.trim().length<2} onClick={submit}><UserPlus size={16}/> Crear NPC</button></div></div>
}

function CampaignManager({campaigns,current,close,select,refresh}:{campaigns:Campaign[];current:string;close:()=>void;select:(id:string)=>void;refresh:()=>Promise<void>}) {
  const [name,setName]=useState('');const [templates,setTemplates]=useState<CampaignTemplate[]>([]);const [template,setTemplate]=useState<CampaignTemplate['id']>('blank');const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  useEffect(()=>{void api.campaignTemplates().then(setTemplates).catch(()=>setTemplates([]))},[])
  const create=async()=>{setBusy(true);try{const item=await api.createFromTemplate(template,name);await refresh();select(item.id);close()}catch(e){setError(e instanceof Error?e.message:'No s’ha pogut crear')}finally{setBusy(false)}}
  const importFile=async(file?:File)=>{if(!file)return;try{await api.importCampaign(JSON.parse(await file.text()));await refresh();close()}catch(e){setError(e instanceof Error?e.message:'Importació no vàlida')}}
  const archive=async(campaign:Campaign)=>{if(!confirm(`Arxivar ${campaign.name}?`))return;await api.updateCampaign(campaign.id,{archived:true});await refresh();const alternative=campaigns.find(x=>x.id!==campaign.id&&!x.archived);if(campaign.id===current&&alternative)select(alternative.id)}
  return <div className="drawer-overlay" onMouseDown={close}><div className="modal wide" onMouseDown={e=>e.stopPropagation()}><button className="icon-button close" onClick={close}><X/></button><span className="eyebrow">Campaign Studio</span><h2>Campanyes</h2><div className="campaign-list">{campaigns.map(item=><div key={item.id} className={item.archived?'archived':''}><button className="campaign-choice" onClick={()=>{select(item.id);close()}}><strong>{item.name}</strong><span>{item.system} · dia {item.current_day}{item.archived?' · arxivada':''}</span></button>{!item.archived&&<button className="icon-button danger" title="Arxivar" onClick={()=>archive(item)}><Archive size={15}/></button>}</div>)}</div><div className="split-form"><div><h3>Nova campanya</h3><Field label="Nom"><input value={name} onChange={e=>setName(e.target.value)} placeholder="La meva nova campanya"/></Field><div className="template-grid">{templates.map(item=><button className={template===item.id?'selected':''} key={item.id} onClick={()=>setTemplate(item.id)}><strong>{item.name}</strong><small>{item.description}</small></button>)}</div><button className="primary" disabled={busy||name.trim().length<2} onClick={create}><Plus size={15}/>{busy?'Preparant…':'Crear des de plantilla'}</button></div><div><h3>Importar paquet</h3><p className="muted">Restaura una campanya exportada en JSON. Els documents oficials no formen part del paquet.</p><input type="file" accept="application/json,.json" onChange={e=>importFile(e.target.files?.[0])}/></div></div>{error&&<div className="alert">{error}</div>}</div></div>
}

function LibraryView({data,changed}:{data:Dashboard;changed:()=>void}) {
  const [file,setFile]=useState<File|null>(null);const [title,setTitle]=useState('');const [sourceType,setSourceType]=useState('official');const [uploadVisibility,setUploadVisibility]=useState<'dm'|'players'>('dm');const [query,setQuery]=useState('');const [results,setResults]=useState<DocumentResult[]>([]);const [selected,setSelected]=useState<DocumentResult|null>(null);const [lore,setLore]=useState({title:'',content:'',layer:'dm' as 'dm'|'players'|'world',category:'lore',location_id:''});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('')
  const upload=async()=>{if(!file)return;setBusy(true);setError('');try{const form=new FormData();form.append('file',file);form.append('campaign_id',data.campaign.id);form.append('title',title);form.append('source_type',sourceType);form.append('visibility',uploadVisibility);await api.uploadDocument(form);setFile(null);setTitle('');changed()}catch(e){setError(e instanceof Error?e.message:'No s’ha pogut carregar')}finally{setBusy(false)}}
  const search=async()=>{if(query.trim().length>=2){setBusy(true);try{setResults(await api.searchLibrary(data.campaign.id,query))}finally{setBusy(false)}}}
  const prepareLore=(result:DocumentResult)=>{setSelected(result);setLore({title:query.trim()||result.source_title,content:result.content||result.excerpt.replace(/…$/,''),layer:'dm',category:'lore',location_id:''})}
  const approveLore=async()=>{if(!selected||lore.title.trim().length<2)return;setBusy(true);try{await api.documentToLore(data.campaign.id,{chunk_id:selected.chunk_id,...lore,location_id:lore.location_id||undefined});setNotice('Fragment incorporat a Coneixement amb la seva font i pàgina.');setSelected(null);changed()}catch(e){setError(e instanceof Error?e.message:'No s’ha pogut incorporar')}finally{setBusy(false)}}
  const setVisibility=async(id:string,visibility:'dm'|'players')=>{await api.updateDocument(id,{visibility});changed()}
  const remove=async(id:string)=>{if(!confirm('Eliminar el document local i el seu índex?'))return;await api.deleteDocument(id);changed()}
  return <div className="studio-page library-studio"><div className="studio-heading"><div><span className="eyebrow">Biblioteca local</span><h1>Fonts de campanya</h1><p>Documents privats, cercables i separats del repositori Git.</p></div><Archive/></div>{notice&&<div className="notice" onClick={()=>setNotice('')}>{notice}<X size={14}/></div>}<details className="studio-card library-upload" open={!data.sources.length}><summary>Pujar una font local</summary><div className="upload-zone"><FileText/><input type="file" accept=".pdf,.txt,.md,.png,.jpg,.jpeg,.webp" onChange={e=>setFile(e.target.files?.[0]??null)}/><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Títol opcional"/><select value={sourceType} onChange={e=>setSourceType(e.target.value)}><option value="official">Font oficial pròpia</option><option value="homebrew">Homebrew</option><option value="notes">Notes del DM</option></select><select value={uploadVisibility} onChange={e=>setUploadVisibility(e.target.value as 'dm'|'players')}><option value="dm">Només DM</option><option value="players">Compartible</option></select><button className="primary" disabled={!file||busy} onClick={upload}>{busy?'Processant…':'Pujar i indexar'}</button></div>{error&&<div className="alert">{error}</div>}</details><section className="studio-card"><div className="section-head"><div><h2>Documents i mapes</h2><p>{data.sources.length} fonts locals · no s’inclouen als exports JSON</p></div></div><div className="source-list">{data.sources.map(source=><div key={source.id}><FileText/><div><strong>{source.title}</strong><p>{source.file_name} · {source.page_count} pàgines · {source.chunk_count} fragments</p></div><select value={source.visibility} onChange={e=>void setVisibility(source.id,e.target.value as 'dm'|'players')}><option value="dm">Només DM</option><option value="players">Jugadors</option></select><span className={source.status==='ready'?'ready':'warning-text'}>{source.status==='ready'?'Preparat':'Necessita OCR'}</span><button onClick={()=>window.open(`/api/library/${source.id}/asset`,'gm-ai-source')}>Obrir</button><button className="icon-button danger" onClick={()=>remove(source.id)}><Trash2 size={14}/></button></div>)}{!data.sources.length&&<p className="empty-search">Encara no hi ha documents o mapes.</p>}</div></section><section className="studio-card"><div className="library-search"><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&void search()} placeholder="Cerca persones, llocs, regles o objectes..."/><button disabled={busy||query.trim().length<2} onClick={()=>void search()}><Search size={16}/>{busy?'Cercant…':'Cercar'}</button></div><p className="muted">La cerca és local i conserva la pàgina d’origen. Revisa sempre el text abans d’incorporar-lo al món.</p><div className="document-results">{results.map(result=><article className="document-result" key={result.chunk_id}><header><strong>{result.source_title}</strong><span>{result.page?`Pàgina ${result.page}`:'Text local'} · rellevància {result.score}</span></header><p>{result.excerpt}</p><button onClick={()=>prepareLore(result)}><Plus size={14}/> Convertir en coneixement</button></article>)}{query&&results.length===0&&!busy&&<p className="empty-search">Cap fragment coincideix amb la cerca.</p>}</div></section>{selected&&<div className="drawer-overlay" onMouseDown={()=>setSelected(null)}><div className="modal document-review" onMouseDown={e=>e.stopPropagation()}><button className="icon-button close" onClick={()=>setSelected(null)}><X/></button><span className="eyebrow">Aprovació documental</span><h2>Incorporar fragment</h2><p className="muted">{selected.source_title}{selected.page?` · pàgina ${selected.page}`:''}. El text només es persistirà quan premis Aprovar.</p><Field label="Títol"><input value={lore.title} onChange={e=>setLore({...lore,title:e.target.value})}/></Field><div className="two-columns"><Field label="Capa"><select value={lore.layer} onChange={e=>setLore({...lore,layer:e.target.value as typeof lore.layer})}><option value="dm">Només DM</option><option value="players">Coneixement dels jugadors</option><option value="world">Estat real del món</option></select></Field><Field label="Categoria"><select value={lore.category} onChange={e=>setLore({...lore,category:e.target.value})}><option value="lore">Lore</option><option value="npc">NPC</option><option value="location">Ubicació</option><option value="quest">Missió</option><option value="rule">Regla</option><option value="other">Altres</option></select></Field></div><Field label="Ubicació vinculada"><select value={lore.location_id} onChange={e=>setLore({...lore,location_id:e.target.value})}><option value="">Cap ubicació</option>{data.locations.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></Field><Field label="Text revisat"><textarea rows={10} value={lore.content} onChange={e=>setLore({...lore,content:e.target.value})}/></Field><button className="primary full" disabled={busy||lore.title.trim().length<2||lore.content.trim().length<2} onClick={()=>void approveLore()}><Save size={15}/> Aprovar i incorporar</button></div></div>}</div>
}

function WorldStudio({data,changed}:{data:Dashboard;changed:()=>void}) {
  const [campaignName,setCampaignName]=useState(data.campaign.name);const [day,setDay]=useState(data.campaign.current_day);const [party,setParty]=useState({...data.party});const [newLocation,setNewLocation]=useState({name:'',description:'',terrain:'urban'});const [variable,setVariable]=useState({key:'',value:''});const [editLocation,setEditLocation]=useState<Location|null>(null)
  const saveCampaign=async()=>{await api.updateCampaign(data.campaign.id,{name:campaignName,current_day:day});changed()}
  const saveParty=async()=>{await api.updateParty(data.campaign.id,{name:party.name,level:party.level,size:party.size,notes:party.notes});changed()}
  const createLocation=async()=>{await api.createLocation(data.campaign.id,newLocation);setNewLocation({name:'',description:'',terrain:'urban'});changed()}
  const saveLocation=async()=>{if(!editLocation)return;await api.updateLocation(editLocation.id,editLocation);setEditLocation(null);changed()}
  const activate=async(id:string)=>{await api.updateCampaign(data.campaign.id,{current_location_id:id});changed()}
  const removeLocation=async(id:string)=>{if(!confirm('Eliminar aquesta localització?'))return;await api.deleteLocation(id);changed()}
  const addVariable=async()=>{if(variable.key.trim().length<2)return;await api.setWorldState(data.campaign.id,variable.key,variable.value);setVariable({key:'',value:''});changed()}
  return <div className="studio-page"><div className="studio-heading"><div><span className="eyebrow">Campaign Studio</span><h1>Món i grup</h1><p>Configura la font de veritat que utilitzaran els motors.</p></div><Map/></div><div className="studio-grid"><section className="studio-card"><h2>Campanya</h2><Field label="Nom"><input value={campaignName} onChange={e=>setCampaignName(e.target.value)}/></Field><Field label="Dia actual"><input type="number" min="1" value={day} onChange={e=>setDay(Number(e.target.value))}/></Field><button className="primary" onClick={saveCampaign}><Save size={15}/> Desar</button></section><section className="studio-card"><h2>Grup</h2><Field label="Nom"><input value={party.name} onChange={e=>setParty({...party,name:e.target.value})}/></Field><div className="two-columns"><Field label="Nivell"><input type="number" min="1" max="20" value={party.level} onChange={e=>setParty({...party,level:Number(e.target.value)})}/></Field><Field label="Mida"><input type="number" min="1" max="12" value={party.size} onChange={e=>setParty({...party,size:Number(e.target.value)})}/></Field></div><Field label="Notes"><textarea value={party.notes} onChange={e=>setParty({...party,notes:e.target.value})}/></Field><button className="primary" onClick={saveParty}><Save size={15}/> Desar grup</button></section></div><section className="studio-card"><div className="section-head"><div><h2>Localitzacions</h2><p>La localització activa alimenta encounters, recompenses i context.</p></div></div><div className="entity-grid">{data.locations.map(item=><article className={item.id===data.campaign.current_location_id?'entity-card active-entity':'entity-card'} key={item.id}><span>{terrainNames[item.terrain]??item.terrain}</span><h3>{item.name}</h3><p>{item.description||'Sense descripció.'}</p><div className="button-row">{item.id!==data.campaign.current_location_id&&<button onClick={()=>activate(item.id)}>Fer activa</button>}<button onClick={()=>setEditLocation({...item})}>Editar</button>{item.id!==data.campaign.current_location_id&&<button className="danger" onClick={()=>removeLocation(item.id)}><Trash2 size={14}/></button>}</div></article>)}</div>{editLocation&&<div className="inline-editor"><h3>Editar localització</h3><Field label="Nom"><input value={editLocation.name} onChange={e=>setEditLocation({...editLocation,name:e.target.value})}/></Field><Field label="Descripció"><textarea value={editLocation.description} onChange={e=>setEditLocation({...editLocation,description:e.target.value})}/></Field><Field label="Terreny"><select value={editLocation.terrain} onChange={e=>setEditLocation({...editLocation,terrain:e.target.value})}>{terrains.map(x=><option key={x} value={x}>{terrainNames[x]}</option>)}</select></Field><div className="button-row"><button onClick={()=>setEditLocation(null)}>Cancel·lar</button><button className="primary" onClick={saveLocation}>Desar</button></div></div>}<div className="inline-create"><input value={newLocation.name} onChange={e=>setNewLocation({...newLocation,name:e.target.value})} placeholder="Nova localització"/><input value={newLocation.description} onChange={e=>setNewLocation({...newLocation,description:e.target.value})} placeholder="Descripció breu"/><select value={newLocation.terrain} onChange={e=>setNewLocation({...newLocation,terrain:e.target.value})}>{terrains.map(x=><option key={x} value={x}>{terrainNames[x]}</option>)}</select><button className="primary" disabled={newLocation.name.trim().length<2} onClick={createLocation}><Plus size={15}/> Afegir</button></div></section><section className="studio-card"><h2>Variables del món</h2><div className="variable-list">{Object.entries(data.world_state).map(([key,value])=><div key={key}><code>{key}</code><strong>{String(value)}</strong>{key!=='wanted_level'&&!key.startsWith('reputation:')&&<button className="icon-button danger" onClick={async()=>{await api.deleteWorldState(data.campaign.id,key);changed()}}><X size={13}/></button>}</div>)}</div><div className="inline-create"><input value={variable.key} onChange={e=>setVariable({...variable,key:e.target.value})} placeholder="clau_personalitzada"/><input value={variable.value} onChange={e=>setVariable({...variable,value:e.target.value})} placeholder="Valor"/><button onClick={addVariable}><Plus size={15}/> Afegir</button></div></section></div>
}

function FactionStudio({data,changed}:{data:Dashboard;changed:()=>void}) {
  const [form,setForm]=useState({name:'',description:''});const [editing,setEditing]=useState<Faction|null>(null)
  const create=async()=>{await api.createFaction(data.campaign.id,form);setForm({name:'',description:''});changed()}
  const save=async()=>{if(!editing)return;await api.updateFaction(editing.id,editing);setEditing(null);changed()}
  const remove=async(id:string)=>{if(!confirm('Eliminar la facció? Els NPC quedaran sense facció.'))return;await api.deleteFaction(id);changed()}
  return <div className="studio-page"><div className="studio-heading"><div><span className="eyebrow">Teixit polític</span><h1>Faccions</h1><p>Organitzacions, influència i reputació persistent.</p></div><Shield/></div><div className="entity-grid">{data.factions.map(item=><article className="entity-card" key={item.id}><span>Reputació {data.world_state[`reputation:${item.id}`]??0}</span><h3>{item.name}</h3><p>{item.description||'Sense descripció.'}</p><small>{data.npcs.filter(n=>n.faction_id===item.id).length} NPC vinculats</small><div className="button-row"><button onClick={()=>setEditing({...item})}>Editar</button><button className="danger" onClick={()=>remove(item.id)}><Trash2 size={14}/></button></div></article>)}</div>{editing&&<section className="studio-card inline-editor"><h2>Editar facció</h2><Field label="Nom"><input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})}/></Field><Field label="Descripció"><textarea value={editing.description} onChange={e=>setEditing({...editing,description:e.target.value})}/></Field><div className="button-row"><button onClick={()=>setEditing(null)}>Cancel·lar</button><button className="primary" onClick={save}>Desar</button></div></section>}<section className="studio-card"><h2>Nova facció</h2><div className="inline-create"><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Nom de la facció"/><input value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Objectius i influència"/><button className="primary" disabled={form.name.trim().length<2} onClick={create}><Plus size={15}/> Crear</button></div></section></div>
}

function ReferenceCatalog({data,changed}:{data:Dashboard;changed:()=>void}) {
  const categories = [
    ['magic-items','Objectes màgics'],['equipment','Equipament'],['monsters','Monstres'],['spells','Encanteris'],['conditions','Condicions'],
  ] as const
  const [category,setCategory]=useState<string>('magic-items');const [query,setQuery]=useState('');const [items,setItems]=useState<ReferenceItem[]>([]);const [total,setTotal]=useState(0);const [selected,setSelected]=useState<ReferenceItem|null>(null);const [targetTable,setTargetTable]=useState('');const [busy,setBusy]=useState(false)
  const search=async()=>{setBusy(true);try{const result=await api.reference(query,category);setItems(result.items);setTotal(result.total);setSelected(result.items[0]??null)}finally{setBusy(false)}}
  useEffect(()=>{let active=true;void api.reference('',category).then(result=>{if(active){setItems(result.items);setTotal(result.total);setSelected(result.items[0]??null)}});return()=>{active=false}},[category])
  const compatibleTables=category==='conditions'?[]:data.generation_tables.filter(table=>category==='monsters'?table.kind==='encounter':table.kind==='reward')
  const addToTable=async()=>{if(!selected||!targetTable)return;const encounter=category==='monsters';const payload=encounter?{type:'combat',description:selected.summary||`Encounter amb ${selected.name}`,objectives:[`Gestionar l'amenaça de ${selected.name}`],complications:[],reference_id:selected.id}:{items:[{name:selected.name,quantity:1,category:selected.category,reference_id:selected.id}],narrative:[],reference_id:selected.id};await api.createEntry(targetTable,{terrains:[],min_level:1,max_level:20,min_difficulty:1,max_difficulty:5,weight:1,title:selected.name,payload,tags:[...selected.tags,'srd']});changed()}
  const detailRows=selected?Object.entries(selected.data).filter(([,value])=>typeof value==='string'||typeof value==='number').slice(0,8):[]
  return <div className="studio-page"><div className="studio-heading"><div><span className="eyebrow">SRD 5.1 · CC-BY-4.0</span><h1>Catàleg de referència</h1><p>1.267 entrades obertes disponibles sense connexió.</p></div><BookOpen/></div><div className="catalog-tabs">{categories.map(([id,label])=><button className={category===id?'active':''} key={id} onClick={()=>setCategory(id)}>{label}</button>)}</div><div className="catalog-search"><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&search()} placeholder="Cerca per nom, tipus, escola o descripció..."/><button onClick={search}><Search size={15}/>{busy?'Cercant…':`Cercar entre ${total}`}</button></div><div className="catalog-layout"><section className="catalog-results">{items.map(item=><button className={selected?.id===item.id?'active':''} key={item.id} onClick={()=>setSelected(item)}><div><strong>{item.name}</strong><span>{item.tags.slice(1,4).join(' · ')||item.category}</span></div><ChevronRight size={15}/></button>)}</section><section className="studio-card catalog-detail">{selected?<><span className="eyebrow">{selected.category} · {selected.license}</span><h2>{selected.name}</h2><p>{selected.summary||'Entrada mecànica de referència de l’SRD.'}</p><div className="reference-facts">{detailRows.map(([key,value])=><div key={key}><span>{key.replaceAll('_',' ')}</span><strong>{String(value)}</strong></div>)}</div><details><summary>Dades estructurades</summary><pre>{JSON.stringify(selected.data,null,2)}</pre></details>{category!=='conditions'&&<div className="reference-action"><Field label="Afegir a una taula custom"><select value={targetTable} onChange={e=>setTargetTable(e.target.value)}><option value="">Selecciona una taula compatible</option>{compatibleTables.map(table=><option value={table.id} key={table.id}>{table.name}</option>)}</select></Field><button className="primary" disabled={!targetTable} onClick={addToTable}><Plus size={15}/> Afegir com entrada</button></div>}<small className="attribution">{selected.source} · Consulta NOTICE-SRD.md</small></>:<div className="empty"><BookOpen/><p>Selecciona una entrada.</p></div>}</section></div></div>
}

function TableStudio({data,changed}:{data:Dashboard;changed:()=>void}) {
  const tables=data.generation_tables;const [selected,setSelected]=useState(tables[0]?.id??'');const [entries,setEntries]=useState<GenerationEntry[]>([]);const [tableForm,setTableForm]=useState<{name:string;description:string;kind:'encounter'|'reward'}>({name:'',description:'',kind:'encounter'});const [entryForm,setEntryForm]=useState({title:'',terrains:['urban'],min_level:1,max_level:20,min_difficulty:1,max_difficulty:5,weight:1,description:'',tags:''})
  useEffect(()=>{if(selected)void api.entries(selected).then(setEntries)},[selected])
  const current=tables.find(x=>x.id===selected)
  const createTable=async()=>{const item=await api.createTable(data.campaign.id,tableForm);setTableForm({...tableForm,name:'',description:''});setSelected(item.id);changed()}
  const removeTable=async()=>{if(!current||!confirm(`Eliminar la taula ${current.name} i totes les entrades?`))return;await api.deleteTable(current.id);const next=await api.tables(data.campaign.id);setSelected(next[0]?.id??'');setEntries([]);changed()}
  const createEntry=async()=>{if(!current)return;const payload=current.kind==='encounter'?{type:'mixed',description:entryForm.description,objectives:[],complications:[]}:{items:[{name:entryForm.description||entryForm.title,quantity:1,category:'custom'}],narrative:[]};await api.createEntry(current.id,{terrains:entryForm.terrains,min_level:entryForm.min_level,max_level:entryForm.max_level,min_difficulty:entryForm.min_difficulty,max_difficulty:entryForm.max_difficulty,weight:entryForm.weight,title:entryForm.title,payload,tags:entryForm.tags.split(',').map(x=>x.trim()).filter(Boolean)});setEntryForm({...entryForm,title:'',description:'',tags:''});setEntries(await api.entries(current.id))}
  const removeEntry=async(id:string)=>{if(!confirm('Eliminar aquesta entrada?'))return;await api.deleteEntry(id);if(current)setEntries(await api.entries(current.id))}
  const toggleTerrain=(terrain:string)=>setEntryForm({...entryForm,terrains:entryForm.terrains.includes(terrain)?entryForm.terrains.filter(x=>x!==terrain):[...entryForm.terrains,terrain]})
  return <div className="studio-page"><div className="studio-heading"><div><span className="eyebrow">Contingut ampliable</span><h1>Taules homebrew</h1><p>Defineix opcions contextuals sense modificar el motor.</p></div><Dices/></div><div className="table-layout"><aside className="table-sidebar"><h3>Taules</h3>{tables.map(item=><button className={selected===item.id?'active':''} key={item.id} onClick={()=>setSelected(item.id)}><span>{item.kind==='encounter'?'⚔':'◆'}</span><div><strong>{item.name}</strong><small>{item.kind}</small></div></button>)}<div className="table-create"><input value={tableForm.name} onChange={e=>setTableForm({...tableForm,name:e.target.value})} placeholder="Nova taula"/><select value={tableForm.kind} onChange={e=>setTableForm({...tableForm,kind:e.target.value as 'encounter'|'reward'})}><option value="encounter">Encounters</option><option value="reward">Recompenses</option></select><button disabled={tableForm.name.trim().length<2} onClick={createTable}><Plus size={14}/> Crear</button></div></aside><section className="studio-card">{current?<><div className="section-head"><div><h2>{current.name}</h2><p>{current.description||`${entries.length} entrades configurades`}</p></div><button className="danger" onClick={removeTable}><Trash2 size={14}/> Eliminar taula</button></div><div className="entry-list">{entries.map(item=><article key={item.id}><div><strong>{item.title}</strong><span>{item.terrains.map(x=>terrainNames[x]??x).join(', ')||'Qualsevol terreny'} · nivells {item.min_level}–{item.max_level} · dificultat {item.min_difficulty}–{item.max_difficulty} · pes {item.weight}</span></div><button className="icon-button danger" onClick={()=>removeEntry(item.id)}><Trash2 size={14}/></button></article>)}</div><div className="entry-editor"><h3>Afegir entrada</h3><Field label="Títol"><input value={entryForm.title} onChange={e=>setEntryForm({...entryForm,title:e.target.value})}/></Field><Field label={current.kind==='encounter'?'Descripció':'Objecte o recompensa'}><textarea value={entryForm.description} onChange={e=>setEntryForm({...entryForm,description:e.target.value})}/></Field><span className="field-caption">Terrenys</span><div className="chip-list">{terrains.map(x=><button className={entryForm.terrains.includes(x)?'selected':''} key={x} onClick={()=>toggleTerrain(x)}>{terrainNames[x]}</button>)}</div><div className="four-columns"><Field label="Nivell mín."><input type="number" min="1" max="20" value={entryForm.min_level} onChange={e=>setEntryForm({...entryForm,min_level:Number(e.target.value)})}/></Field><Field label="Nivell màx."><input type="number" min="1" max="20" value={entryForm.max_level} onChange={e=>setEntryForm({...entryForm,max_level:Number(e.target.value)})}/></Field><Field label="Dificultat mín."><input type="number" min="1" max="5" value={entryForm.min_difficulty} onChange={e=>setEntryForm({...entryForm,min_difficulty:Number(e.target.value)})}/></Field><Field label="Dificultat màx."><input type="number" min="1" max="5" value={entryForm.max_difficulty} onChange={e=>setEntryForm({...entryForm,max_difficulty:Number(e.target.value)})}/></Field></div><div className="two-columns"><Field label="Pes"><input type="number" min="1" max="1000" value={entryForm.weight} onChange={e=>setEntryForm({...entryForm,weight:Number(e.target.value)})}/></Field><Field label="Etiquetes"><input value={entryForm.tags} onChange={e=>setEntryForm({...entryForm,tags:e.target.value})} placeholder="homebrew, lore"/></Field></div><button className="primary" disabled={entryForm.title.trim().length<2} onClick={createEntry}><Plus size={15}/> Afegir entrada</button></div></>:<div className="empty"><Dices/><p>Crea una taula per començar.</p></div>}</section></div></div>
}

function GeneratorPanel({kind,data,close,done}:{kind:GeneratorKind;data:Dashboard;close:()=>void;done:()=>void}) {
  const [terrain,setTerrain]=useState(data.location.terrain||'urban');const [difficulty,setDifficulty]=useState(3);const [level,setLevel]=useState(data.party.level);const [partySize,setPartySize]=useState(data.party.size);const [type,setType]=useState('auto');const [fortuneMode,setFortuneMode]=useState<'neutral'|'automatic'|'manual'>('neutral');const [fortuneRoll,setFortuneRoll]=useState(10);const [encounterId,setEncounterId]=useState(data.encounters[0]?.id??'');const [result,setResult]=useState<Encounter|Reward|null>(kind==='encounter'?(data.encounters[0]??null):(data.rewards[0]??null));const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const generate=async()=>{setBusy(true);setError('');try{if(kind==='encounter')setResult(await api.generateEncounter(data.campaign.id,{location_id:data.location.id,terrain,party_level:level,party_size:partySize,difficulty,encounter_type:type}));else setResult(await api.generateReward(data.campaign.id,{location_id:data.location.id,encounter_id:encounterId||null,terrain,party_level:level,difficulty,mode:fortuneMode==='neutral'?'neutral':'fortune',fortune_roll:fortuneMode==='manual'?fortuneRoll:null}));done()}catch(e){setError(e instanceof Error?e.message:'No s’ha pogut generar')}finally{setBusy(false)}}
  const invalidManualRoll=kind==='reward'&&fortuneMode==='manual'&&(!Number.isInteger(fortuneRoll)||fortuneRoll<1||fortuneRoll>20)
  return <div className="drawer-overlay" onMouseDown={close}><div className="modal generator-modal" onMouseDown={e=>e.stopPropagation()}><button className="icon-button close" onClick={close}><X/></button><span className="eyebrow">{kind==='encounter'?'Encounter Engine':'Reward Engine'}</span><h2>{kind==='encounter'?'Crear encounter':'Generar recompensa'}</h2>{kind==='reward'&&<Field label="Encounter relacionat"><select value={encounterId} onChange={e=>setEncounterId(e.target.value)}><option value="">Cap encounter concret</option>{data.encounters.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select></Field>}<div className="generator-grid"><Field label="Terreny"><select value={terrain} onChange={e=>setTerrain(e.target.value)}>{terrains.map(item=><option value={item} key={item}>{terrainNames[item]}</option>)}</select></Field><Field label="Nivell del grup"><input type="number" min="1" max="20" value={level} onChange={e=>setLevel(Number(e.target.value))}/></Field>{kind==='encounter'&&<Field label="Mida del grup"><input type="number" min="1" max="12" value={partySize} onChange={e=>setPartySize(Number(e.target.value))}/></Field>}{kind==='encounter'?<Field label="Tipus"><select value={type} onChange={e=>setType(e.target.value)}><option value="auto">Automàtic</option><option value="combat">Combat</option><option value="social">Social</option><option value="exploration">Exploració</option><option value="hazard">Perill</option><option value="mixed">Mixt</option></select></Field>:<Field label="Fortuna"><select value={fortuneMode} onChange={e=>setFortuneMode(e.target.value as typeof fortuneMode)}><option value="neutral">Sense tirada de fortuna</option><option value="automatic">Tirada automàtica d20</option><option value="manual">Resultat dels jugadors</option></select></Field>}</div>{kind==='reward'&&fortuneMode==='manual'&&<div className="manual-roll"><div className="die-mark"><Dices size={20}/><span>d20</span></div><Field label="Resultat de la tirada"><input type="number" min="1" max="20" step="1" value={fortuneRoll} onChange={e=>setFortuneRoll(Number(e.target.value))}/></Field><p>Introdueix el resultat que han tret els jugadors (1–20).</p></div>}<label className="range-label"><span>Dificultat <b>{difficultyNames[difficulty]}</b></span><input type="range" min="1" max="5" value={difficulty} onChange={e=>setDifficulty(Number(e.target.value))}/><div><small>Fàcil</small><small>Mortal</small></div></label><button className="primary full" onClick={generate} disabled={busy||invalidManualRoll}>{busy?'Generant…':kind==='encounter'?'Generar encounter':'Generar recompensa'}</button>{invalidManualRoll&&<div className="alert">La tirada de fortuna ha de ser un nombre enter entre 1 i 20.</div>}{error&&<div className="alert">{error}</div>}{result&&<div className="generated-result"><span>{terrainNames[result.terrain]??result.terrain} · dificultat {result.difficulty}/5{'fortune_roll'in result&&result.fortune_roll?` · fortuna ${result.fortune_roll}/20`:''}</span><h3>{result.title}</h3>{'description'in result&&<p>{result.description}</p>}{'objectives'in result&&result.objectives.map(item=><p key={item}>Objectiu: {item}</p>)}{'items'in result&&result.items.map((item,index)=><p key={index}>◆ {item.quantity??1} × {item.name}</p>)}<details><summary>Per què aquesta opció?</summary>{result.context_reasons.map(reason=><p key={reason}>{reason}</p>)}</details></div>}</div></div>
}

function PreferenceToggle({label,description,checked,onChange,disabled=false}:{label:string;description:string;checked:boolean;onChange:(value:boolean)=>void;disabled?:boolean}){
  return <label className={`preference-toggle ${disabled?'disabled':''}`}><span><strong>{label}</strong><small>{description}</small></span><input type="checkbox" checked={checked} disabled={disabled} onChange={e=>onChange(e.target.checked)}/><i/></label>
}

function SettingsPanel({value,change,close}:{value:UIPreferences;change:(next:UIPreferences)=>void;close:()=>void}){
  const visible=Object.values(value.modules).filter(Boolean).length
  const setModule=(id:ConfigurableModule,enabled:boolean)=>change({...value,modules:{...value.modules,[id]:enabled,session:true}})
  const showAll=()=>change({...value,modules:{...defaultPreferences.modules}})
  const essentials=()=>{const modules={...value.modules};for(const key of Object.keys(modules) as ConfigurableModule[])modules[key]=false;modules.session=true;modules.world=true;modules.hexcrawl=true;modules.combat=true;change({...value,modules})}
  return <div className="drawer-overlay" onMouseDown={close}><aside className="settings-drawer" onMouseDown={e=>e.stopPropagation()}><button className="icon-button close" onClick={close}><X/></button><span className="eyebrow">Preferències locals</span><h2>Configuració de la interfície</h2><p className="muted">Adapta la taula a cada partida. Aquestes opcions es desen només en aquest navegador.</p><div className="settings-summary"><SlidersHorizontal/><span><strong>{visible} eines visibles</strong><small>La vista Sessió sempre queda disponible.</small></span></div><div className="settings-actions"><button onClick={showAll}>Mostrar-ho tot</button><button onClick={essentials}>Mode essencial</button></div><section><h3>Visibilitat dels mòduls</h3><div className="module-settings">{navItems.map(([id,,label,description])=><PreferenceToggle key={id} label={label} description={description} checked={value.modules[id]} disabled={id==='session'} onChange={enabled=>setModule(id,enabled)}/>)}</div></section><details className="settings-group" open><summary>Generadors ràpids</summary><PreferenceToggle label="Encounter Engine" description="Accés directe des del menú lateral." checked={value.modules.encounter} onChange={enabled=>setModule('encounter',enabled)}/><PreferenceToggle label="Reward Engine" description="Generació contextual de recompenses." checked={value.modules.reward} onChange={enabled=>setModule('reward',enabled)}/></details><details className="settings-group"><summary>Aparença i accessibilitat</summary><PreferenceToggle label="Interfície compacta" description="Redueix espais per mostrar més informació." checked={value.compact} onChange={compact=>change({...value,compact})}/><PreferenceToggle label="Panell de context" description="Mostra ubicació, grup, rumors i eines ràpides." checked={value.showContextPanel} onChange={showContextPanel=>change({...value,showContextPanel})}/><PreferenceToggle label="Text ampliat" description="Augmenta lleugerament la mida general del text." checked={value.largeText} onChange={largeText=>change({...value,largeText})}/><PreferenceToggle label="Reduir animacions" description="Minimitza transicions i moviment visual." checked={value.reduceMotion} onChange={reduceMotion=>change({...value,reduceMotion})}/></details><button className="reset-settings" onClick={()=>change(defaultPreferences)}>Restaurar configuració inicial</button></aside></div>
}

export default function App() {
  const [campaigns,setCampaigns]=useState<Campaign[]>([]);const [campaignId,setCampaignId]=useState(localStorage.getItem('gm-ai-campaign')??'demo');const [data,setData]=useState<Dashboard|null>(null);const [view,setView]=useState<View>(loadInitialView);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const [manager,setManager]=useState(false);const [settingsOpen,setSettingsOpen]=useState(false);const [preferences,setPreferences]=useState<UIPreferences>(loadPreferences);const [creatingNpc,setCreatingNpc]=useState(false);const [selectedNpc,setSelectedNpc]=useState<NPC|null>(null);const [generator,setGenerator]=useState<GeneratorKind|null>(null);const [eventText,setEventText]=useState('');const [npcId,setNpcId]=useState('');const [visibility,setVisibility]=useState<'private'|'witnessed'|'public'>('public');const [proposal,setProposal]=useState<EventProposal|null>(null);const [searchQuery,setSearchQuery]=useState('')
  const changePreferences=(next:UIPreferences)=>{setPreferences(next);localStorage.setItem(UI_STORAGE_KEY,JSON.stringify(next));if(!next.modules[view])setView('session')}
  const refreshCampaigns=async()=>{const list=await api.campaigns();setCampaigns(list);if(!list.some(x=>x.id===campaignId)){const first=list.find(x=>!x.archived)??list[0];if(first)setCampaignId(first.id)}}
  const load=async()=>{try{setError('');setData(await api.dashboard(campaignId))}catch(e){setError(e instanceof Error?e.message:'No s’ha pogut carregar la campanya')}}
  useEffect(()=>{let active=true;void api.campaigns().then(list=>{if(!active)return;setCampaigns(list);if(!list.some(x=>x.id===campaignId)){const first=list.find(x=>!x.archived)??list[0];if(first)setCampaignId(first.id)}}).catch(e=>{if(active)setError(e instanceof Error?e.message:'No s’han pogut carregar les campanyes')});return()=>{active=false}},[campaignId])
  useEffect(()=>{let active=true;localStorage.setItem('gm-ai-campaign',campaignId);void api.dashboard(campaignId).then(result=>{if(active){setData(result);setError('')}}).catch(e=>{if(active)setError(e instanceof Error?e.message:'No s’ha pogut carregar la campanya')});return()=>{active=false}},[campaignId])
  const activeSession=data?.sessions.find(x=>!x.ended_at)
  const filteredNpcs=useMemo(()=>data?.npcs.filter(n=>n.name.toLowerCase().includes(searchQuery.toLowerCase())||n.traits.join(' ').toLowerCase().includes(searchQuery.toLowerCase()))??[],[data,searchQuery])
  const analyze=async()=>{if(!data||eventText.trim().length<3)return;setBusy(true);try{setProposal(await api.analyzeEvent(data.campaign.id,eventText,npcId||undefined,visibility))}catch(e){setError(e instanceof Error?e.message:'No s’ha pogut analitzar')}finally{setBusy(false)}}
  const toggleSession=async()=>{if(!data)return;setBusy(true);try{if(activeSession){const summary=prompt('Resum de la sessió (opcional):','')??'';await api.endSession(activeSession.id,summary);setNotice('Sessió finalitzada i desada.')}else{await api.startSession(data.campaign.id);setNotice('Sessió iniciada.')}await load()}finally{setBusy(false)}}
  const exportCampaign=async()=>{if(!data)return;const result=await api.exportCampaign(data.campaign.id);const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`gm-ai-${data.campaign.id}.json`;anchor.click();URL.revokeObjectURL(url);setNotice('Campanya exportada.')}
  const visibleNav=navItems.filter(([id])=>preferences.modules[id])
  const uiClass=[preferences.compact?'compact-ui':'',preferences.largeText?'large-text-ui':'',preferences.reduceMotion?'reduce-motion-ui':'',!preferences.showContextPanel?'no-context-ui':''].filter(Boolean).join(' ')
  if(error&&!data)return <main className="offline"><CircleAlert/><h1>No s’ha pogut obrir la campanya</h1><p>{error}</p><button onClick={()=>{void refreshCampaigns();void load()}}>Tornar-ho a provar</button></main>
  if(!data)return <main className="loading"><Sparkles/><span>Carregant el món…</span></main>
  if(view==='tools')return <div className={`tool-standalone ${uiClass}`}><header><div className="brand-mark">GM</div><div><span>Campaign Engine</span><strong>{data.campaign.name}</strong></div><button onClick={()=>setView('session')}><ChevronRight className="back-chevron"/> Tornar a la campanya</button></header><main><SessionToolkit data={data}/></main></div>
  if(view==='operations'||view==='simulation'||view==='party'||view==='players'||view==='knowledge'||view==='hexcrawl'||view==='combat')return <div className={`tool-standalone ${uiClass}`}><header><div className="brand-mark">GM</div><div><span>Campaign Engine</span><strong>{data.campaign.name}</strong></div><button onClick={()=>setView('session')}><ChevronRight className="back-chevron"/> Tornar a la campanya</button></header><main>{view==='operations'&&<OperationsStudio data={data} changed={()=>void load()}/>} {view==='simulation'&&<SimulationStudio data={data} changed={()=>void load()}/>} {view==='party'&&<PartyManager data={data} changed={()=>void load()}/>} {view==='players'&&<PlayerViewManager data={data} changed={()=>void load()}/>} {view==='knowledge'&&<KnowledgeLayers data={data} changed={()=>void load()}/>} {view==='hexcrawl'&&<HexcrawlStudio data={data} changed={()=>void load()}/>} {view==='combat'&&<CombatAssistant data={data} changed={()=>void load()}/>}</main></div>
  if(view==='reference')return <div className={`catalog-standalone ${uiClass}`}><header><div className="brand-mark">GM</div><div><span>Campaign Engine</span><strong>{data.campaign.name}</strong></div><button onClick={()=>setView('session')}><ChevronRight className="back-chevron"/> Tornar a la campanya</button></header><main><ReferenceCatalog key={data.campaign.id} data={data} changed={()=>void load()}/></main></div>
  return <div className={`app-shell ${uiClass}`}>
    <header><div className="brand-mark">GM</div><div><span>Campaign Engine</span><strong>{data.campaign.name}</strong></div><div className="header-meta"><select className="campaign-select" value={campaignId} onChange={e=>setCampaignId(e.target.value)}>{campaigns.filter(x=>!x.archived||x.id===campaignId).map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select><button className="icon-button" onClick={()=>setSettingsOpen(true)} title="Configurar interfície"><SlidersHorizontal/></button><button className="icon-button" onClick={()=>setManager(true)} title="Gestionar campanyes"><Settings2/></button></div></header>
    <nav><p>TAULA DEL DM</p>{visibleNav.map(([id,Icon,label])=><button key={id} className={view===id?'active':''} onClick={()=>setView(id)}><Icon size={19}/><span>{label}</span>{id==='library'&&<small>{data.sources.length}</small>}</button>)}{preferences.modules.encounter&&<button onClick={()=>setGenerator('encounter')}><Swords size={19}/><span>Encounter</span></button>}{preferences.modules.reward&&<button onClick={()=>setGenerator('reward')}><Gift size={19}/><span>Recompensa</span></button>}<div className="nav-foot"><span className="status-dot"/>Local · dades privades</div></nav>
    <main className="workspace">{notice&&<div className="notice" onClick={()=>setNotice('')}>{notice}<X size={14}/></div>}{view==='session'&&<><div className="page-title"><div><span className="eyebrow">Mode sessió</span><h1>Taula de campanya</h1></div><button className={`session-button ${activeSession?'active':''}`} disabled={busy} onClick={toggleSession}><span className="pulse"/>{activeSession?'Finalitzar sessió':'Començar sessió'}</button></div><section className="event-composer"><div className="composer-title"><Sparkles/><div><h2>Què acaba de passar?</h2><p>Revisaràs tots els canvis abans d’aplicar-los.</p></div></div><textarea value={eventText} onChange={e=>setEventText(e.target.value)} placeholder="Descriu un fet rellevant de la sessió..."/><div className="composer-actions"><select value={visibility} onChange={e=>setVisibility(e.target.value as typeof visibility)}><option value="public">Públic · pot generar rumor</option><option value="witnessed">Amb testimonis</option><option value="private">Privat</option></select><select value={npcId} onChange={e=>setNpcId(e.target.value)}><option value="">Cap NPC concret</option>{data.npcs.map(n=><option value={n.id} key={n.id}>{n.name}</option>)}</select><button className="primary" onClick={analyze} disabled={busy||eventText.trim().length<3}>{busy?'Analitzant…':'Analitzar fet'}</button></div></section>{proposal&&<Proposal event={proposal} onDone={()=>{setProposal(null);setEventText('');void load()}}/>}<section><div className="section-head"><div><h2>NPCs</h2><p>Context, memòria i coneixement diferenciat</p></div><div className="section-actions"><input className="compact-search" value={searchQuery} onChange={e=>setSearchQuery(e.target.value)} placeholder="Filtrar NPC..."/><button onClick={()=>setCreatingNpc(true)}><UserPlus size={15}/> Afegir</button></div></div><div className="npc-grid">{filteredNpcs.map(npc=><button className="npc-card" key={npc.id} onClick={()=>setSelectedNpc(npc)}><div className="avatar">{npc.name.slice(0,1)}</div><div><h3>{npc.name}</h3><p>{npc.traits.slice(0,2).join(' · ')||'Sense trets'}</p><span>{data.locations.find(x=>x.id===npc.location_id)?.name??'Ubicació desconeguda'}</span></div><ChevronRight/></button>)}</div></section><section className="timeline"><div className="section-head"><div><h2>Activitat recent</h2><p>Decisions persistents del món</p></div><Clock3/></div>{data.events.slice(0,10).map(event=><div className="timeline-row" key={event.id}><span className={`event-dot ${event.status}`}/><div><h4>{event.title}</h4><p>{event.description}</p></div><div className="timeline-state"><em>{event.status}</em>{event.status==='applied'&&<button className="mini" onClick={async()=>{await api.undoEvent(event.id);void load()}}><Undo2 size={14}/></button>}</div></div>)}{!data.events.length&&<div className="empty"><BookOpen/><p>Encara no hi ha esdeveniments.</p></div>}</section></>}{view==='world'&&<WorldStudio data={data} changed={()=>void load()}/>} {view==='factions'&&<FactionStudio data={data} changed={()=>void load()}/>} {view==='library'&&<LibraryView data={data} changed={()=>void load()}/>} {view==='tables'&&<TableStudio data={data} changed={()=>void load()}/>}</main>
    {preferences.showContextPanel&&<aside className="context-panel"><span className="eyebrow">Context actual</span><h2>{data.location.name}</h2><p>{data.location.description}</p><span className="terrain-badge">{terrainNames[data.location.terrain]??data.location.terrain}</span><div className="metric"><Users/><div><span>{data.party.name}</span><strong>Nivell {data.party.level} · {data.party.size} PJ</strong></div></div><div className="metric warning"><CircleAlert/><div><span>Nivell de cerca</span><strong>{data.world_state.wanted_level??0}</strong></div></div><h3>Eines ràpides</h3>{preferences.modules.encounter&&<button className="quick enabled" onClick={()=>setGenerator('encounter')}><Swords/>Generar encounter <span>{data.encounters.length}</span></button>}{preferences.modules.reward&&<button className="quick enabled" onClick={()=>setGenerator('reward')}><Gift/>Generar recompensa <span>{data.rewards.length}</span></button>}<div className="rumor-summary"><h3>Rumors actius</h3>{data.rumors.slice(0,3).map(r=><div key={r.id}><MessageSquare/><p>{r.content}</p></div>)}{!data.rumors.length&&<p>Cap rumor actiu.</p>}</div><h3>Dades locals</h3><button className="quick enabled" onClick={async()=>{const result=await api.createBackup();setNotice(`Backup creat: ${result.name}`)}}><Database/>Crear backup</button><button className="quick enabled" onClick={exportCampaign}><Download/>Exportar campanya</button></aside>}
    {settingsOpen&&<SettingsPanel value={preferences} change={changePreferences} close={()=>setSettingsOpen(false)}/>}
    {manager&&<CampaignManager campaigns={campaigns} current={campaignId} close={()=>setManager(false)} select={setCampaignId} refresh={refreshCampaigns}/>}
    {creatingNpc&&<CreateNPC data={data} close={()=>setCreatingNpc(false)} done={()=>{setCreatingNpc(false);void load()}}/>}
    {selectedNpc&&<NPCPanel npc={data.npcs.find(x=>x.id===selectedNpc.id)??selectedNpc} data={data} close={()=>setSelectedNpc(null)} changed={()=>void load()}/>}
    {generator&&<GeneratorPanel kind={generator} data={data} close={()=>setGenerator(null)} done={()=>void load()}/>}
  </div>
}
